fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Find the greatest index where `cafe` appears in `cafes`.
    // Since cafes is non-empty, and cafe appears at least once,
    // this will always find some index.
    cafes.iter()
        .rposition(|&x| x == cafe)
        .unwrap()
}

fn solve(cafes: Vec<i8>) -> i8 {
    // We want to find the element whose last occurrence position is minimal.
    // Approach:
    // 1. For each distinct value in cafes, determine its last occurrence position.
    // 2. Select the value that has the smallest last occurrence position.

    // To do this efficiently, we can iterate once over cafes (with index),
    // recording the last occurrence index of each value.
    use std::collections::HashMap;

    let mut last_positions = HashMap::new();

    for (idx, &cafe) in cafes.iter().enumerate() {
        // Each occurrence updates last_positions[cafe] to the latest index.
        last_positions.insert(cafe, idx);
    }

    // Now find the value with minimal last occurrence position.
    // Since ties cannot happen at the same index for different values,
    // choosing the first minimal is fine.
    let (&min_val, _) = last_positions
        .iter()
        .min_by_key(|&(_val, &pos)| pos)
        .unwrap();

    min_val
}